 4	import org.springframework.stereotype.Service;
 5	
 6	/**
 7	 * Builds deterministic greetings for the sample API.
 8	 */
 9	@Service
10	public class GreetingService {
11	
12	  /**
13	   * Creates a greeting after normalizing surrounding and repeated whitespace.
14	   *
15	   * @param name raw name supplied by the caller
16	   * @return greeting response with a normalized name
17	   * @throws IllegalArgumentException when the normalized name is blank
18	   */
19	  public GreetingResponse greet(String name) {
20	    String normalizedName = normalizeName(name);
21	    if (normalizedName.isBlank()) {
22	      throw new IllegalArgumentException("name must not be blank");
23	    }
24	    return new GreetingResponse("Hello, %s!".formatted(normalizedName));
25	  }
26	
27	  private String normalizeName(String name) {
28	    if (name == null) {
29	      return "";
30	    }
31	    return name.trim().replaceAll("\\s+", " ");
32	  }
33	}

