 5	import org.springframework.http.HttpStatus;
 6	import org.springframework.http.ResponseEntity;
 7	import org.springframework.web.bind.MethodArgumentNotValidException;
 8	import org.springframework.web.bind.annotation.ExceptionHandler;
 9	import org.springframework.web.bind.annotation.RestControllerAdvice;
10	import org.springframework.web.method.annotation.HandlerMethodValidationException;
11	
12	/**
13	 * Converts validation failures into a consistent public error response.
14	 */
15	@RestControllerAdvice
16	public class GlobalExceptionHandler {
17	
18	  /**
19	   * Handles invalid JSON request bodies.
20	   *
21	   * @param exception validation exception raised by Spring MVC
22	   * @return a sanitized validation error response
23	   */
24	  @ExceptionHandler(MethodArgumentNotValidException.class)
25	  public ResponseEntity<ErrorResponse> handleInvalidBody(MethodArgumentNotValidException exception) {
26	    return badRequest();
27	  }
28	
29	  /**
30	   * Handles invalid method parameters such as query parameters.
31	   *
32	   * @param exception validation exception raised by Spring MVC
33	   * @return a sanitized validation error response
34	   */
35	  @ExceptionHandler(HandlerMethodValidationException.class)
36	  public ResponseEntity<ErrorResponse> handleInvalidParameter(HandlerMethodValidationException exception) {
37	    return badRequest();
38	  }
39	
40	  /**
41	   * Handles method-level validation failures raised by AOP validation.
42	   *
43	   * @param exception constraint violation raised by Bean Validation
44	   * @return a sanitized validation error response
45	   */
46	  @ExceptionHandler(ConstraintViolationException.class)
47	  public ResponseEntity<ErrorResponse> handleConstraintViolation(ConstraintViolationException exception) {
48	    return badRequest();
49	  }
50	
51	  private ResponseEntity<ErrorResponse> badRequest() {
52	    return ResponseEntity
53	        .status(HttpStatus.BAD_REQUEST)
54	        .body(new ErrorResponse("Request validation failed.", Instant.now()));
55	  }
56	}

