 9	import org.springframework.web.bind.annotation.RestControllerAdvice;
10	import org.springframework.web.method.annotation.HandlerMethodValidationException;
11	
12	/**
13	 * Converts validation failures into a consistent public error response.
14	 */
15	@RestControllerAdvice
16	public class GlobalExceptionHandler {
17	
18	  /**
19	   * Handles invalid JSON request bodies.
20	   *
21	   * @param exception validation exception raised by Spring MVC
22	   * @return a sanitized validation error response
23	   */
