31	   *
32	   * @param exception validation exception raised by Spring MVC
33	   * @return a sanitized validation error response
34	   */
35	  @ExceptionHandler(HandlerMethodValidationException.class)
36	  public ResponseEntity<ErrorResponse> handleInvalidParameter(HandlerMethodValidationException exception) {
37	    return badRequest();
38	  }
39	
40	  /**
41	   * Handles method-level validation failures raised by AOP validation.
42	   *
43	   * @param exception constraint violation raised by Bean Validation
44	   * @return a sanitized validation error response
45	   */
46	  @ExceptionHandler(ConstraintViolationException.class)
47	  public ResponseEntity<ErrorResponse> handleConstraintViolation(ConstraintViolationException exception) {
48	    return badRequest();
49	  }
